-- VERIFICACIÓN POSTERIOR de NEX-067. SOLO LECTURA. Cada fila debe dar ok = true. La ejecuta el responsable en la VM INMEDIATAMENTE después de aplicar la migración:
--   docker exec -i nexit-db psql -U nexit_app -d nexit -v ON_ERROR_STOP=1 < verificar-NEX-067.sql
BEGIN READ ONLY;
SELECT 'tabla documento_electronico_stock_salidas existe y está vacía al aplicar' AS control, to_regclass('public.documento_electronico_stock_salidas') IS NOT NULL AND (SELECT count(*) FROM public.documento_electronico_stock_salidas) = 0 AS ok
UNION ALL SELECT 'PK (empresa, documento, depósito) y unicidad (empresa, movimiento)', EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.documento_electronico_stock_salidas'::regclass AND contype = 'p') AND EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fe_stock_salidas_movimiento_uk' AND contype = 'u')
UNION ALL SELECT 'FK a documento, movimiento y depósito', (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public.documento_electronico_stock_salidas'::regclass AND contype = 'f') = 3
UNION ALL SELECT 'tabla inmutable (disparador UPDATE/DELETE)', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'public.documento_electronico_stock_salidas'::regclass AND tgname = 'fe_stock_salidas_inmutable_trg' AND NOT tgisinternal)
UNION ALL SELECT 'las tres funciones existen, SECURITY DEFINER y con search_path fijo', (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('fe_stock_disponibilidad', 'fe_stock_baja_documento', 'fe_documento_crear_fe_con_stock') AND p.prosecdef AND p.proconfig IS NOT NULL AND array_to_string(p.proconfig, ',') LIKE '%search_path=public, pg_temp%') = 3
UNION ALL SELECT 'el rol de la aplicación NO tiene acceso a la tabla de vínculos', NOT (has_table_privilege('nexit_runtime', 'public.documento_electronico_stock_salidas', 'SELECT') OR has_table_privilege('nexit_runtime', 'public.documento_electronico_stock_salidas', 'INSERT') OR has_table_privilege('nexit_runtime', 'public.documento_electronico_stock_salidas', 'UPDATE') OR has_table_privilege('nexit_runtime', 'public.documento_electronico_stock_salidas', 'DELETE'))
UNION ALL SELECT 'el rol de la aplicación EJECUTA la disponibilidad y la emisión atómica', has_function_privilege('nexit_runtime', 'public.fe_stock_disponibilidad(uuid,uuid,uuid,uuid[])', 'EXECUTE') AND has_function_privilege('nexit_runtime', 'public.fe_documento_crear_fe_con_stock(uuid,uuid,uuid,uuid,text,uuid,text,text,text,numeric,jsonb,jsonb)', 'EXECUTE')
UNION ALL SELECT 'el rol de la aplicación NO ejecuta la baja interna NI la creación de FE sin baja', NOT has_function_privilege('nexit_runtime', 'public.fe_stock_baja_documento(uuid,uuid,uuid,jsonb)', 'EXECUTE') AND NOT has_function_privilege('nexit_runtime', 'public.fe_documento_crear_fe(uuid,uuid,uuid,uuid,text,uuid,text,text,text,numeric,jsonb)', 'EXECUTE')
UNION ALL SELECT 'PUBLIC no ejecuta ninguna función de NEX-067', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a WHERE n.nspname = 'public' AND p.proname IN ('fe_stock_disponibilidad', 'fe_stock_baja_documento', 'fe_documento_crear_fe_con_stock', 'fe_stock_salidas_inmutable') AND a.grantee = 0)
UNION ALL SELECT 'NEX-014 intacta: el motor sigue existiendo con su firma', to_regprocedure('public.inventario_registrar_movimiento(uuid,uuid,text,text,date,uuid,uuid,jsonb,text,uuid,text,text,text)') IS NOT NULL
UNION ALL SELECT 'la emisión original sigue existiendo (la usa el envoltorio)', to_regprocedure('public.fe_documento_crear_fe(uuid,uuid,uuid,uuid,text,uuid,text,text,text,numeric,jsonb)') IS NOT NULL;
ROLLBACK;
